function* idMaker() {
  let index = 1;
  while (true) {
    yield index++; // Pauses here and returns the value
  }
}

const gen = idMaker(); // Returns an iterator, doesn't run the code yet

console.log(gen.next().value); // 1
console.log(gen.next().value); // 2
console.log(gen.next().value); // 3
// We can do this forever, and it will never crash memory!


// --- Passing data INTO a generator ---
function* conversation() {
  const name = yield "What is your name?";
  yield `Hello, ${name}!`;
}

const chat = conversation();
console.log(chat.next().value); // "What is your name?" (Pauses at yield)
console.log(chat.next("Alice").value); // "Hello, Alice!" (Passes Alice in, resumes)
